    }
    )
    }
    

    override fun `eventCount`(`part`: kotlin.UInt, `bar`: kotlin.UInt): kotlin.UInt {
            return FfiConverterUInt.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
