sealed class CoreException: kotlin.Exception() {
    
    /**
     * Input could not be read (bad JSON, MIDI or beat table).
     */
    class Invalid(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * A pipeline step failed on valid input.
     */
    class Failed(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Invalid(
                FfiConverterString.read(buf),
                )
            2 -> CoreException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is CoreException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Invalid -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is CoreException.Failed -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




enum class TalkingUnit {
    
    /**
     * Next event in the part, skipping tie continuations.
     */
    NOTE,
    /**
     * First event of the next bar.
     */
    BAR,
    /**
     * Same time position in the next part.
     */
    PART,
    /**
     * Next note with confidence below 0.7 that has not been checked.
     */
    UNCERTAIN;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeTalkingUnit: FfiConverterRustBuffer<TalkingUnit> {
    override fun read(buf: ByteBuffer) = try {
        TalkingUnit.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: TalkingUnit) = 4UL

    override fun write(value: TalkingUnit, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalInt: FfiConverterRustBuffer<kotlin.Int?> {
    override fun read(buf: ByteBuffer): kotlin.Int? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterInt.read(buf)
    }

    override fun allocationSize(value: kotlin.Int?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Int?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterInt.write(value, buf)
        }
    }
}




